description:
Write helpers that wrap other functions, using closures.

```
const square = memoize(n => { console.log("working"); return n * n; });
square(4)   // prints "working", returns 16
square(4)   // returns 16 straight away
const init = once(() => "ready");
init(), init()  // "ready", "ready" (the function ran once)
const add5 = partial((a, b) => a + b, 5);
add5(10)    // 15
```

starter.main.js:
function memoize(fn) {
  return fn;
}

function once(fn) {
  return fn;
}

function partial(fn, ...first) {
  return fn;
}

const square = memoize(n => { console.log("working"); return n * n; });
console.log(square(4), square(4));
